<script setup>import{onMounted,reactive,ref}from'vue';import http from'@/services/http';import{congeService}from'@/services/congeService';const es=ref([]),soldes=ref([]),msg=ref(''),f=reactive({employeId:'',annee:new Date().getFullYear(),joursAcquis:30,joursReportes:0});async function load(){es.value=(await http.get('/manager/onboarding/employes')).data;soldes.value=await congeService.soldes()}async function save(){await congeService.enregistrerSolde({...f,employeId:Number(f.employeId),annee:Number(f.annee),joursAcquis:Number(f.joursAcquis),joursReportes:Number(f.joursReportes)});msg.value='Solde enregistré.';load()}onMounted(load)</script>
<template><div class="container-fluid py-4"><h1 class="h3">Gestion des soldes de congés</h1><p v-if="msg" class="alert alert-success">{{msg}}</p><form class="card card-body mb-4" @submit.prevent="save"><h2 class="h5">Saisir le solde d’un employé</h2><div class="row g-3"><div class="col-md-3"><label class="form-label">Employé concerné</label><select v-model="f.employeId" class="form-select" required><option value="">Choisir un employé</option><option v-for="e in es" :key="e.id" :value="e.id">{{e.prenom}} {{e.nom}}</option></select></div><div class="col-md-2"><label class="form-label">Année</label><input v-model="f.annee" type="number" class="form-control" required></div><div class="col-md-3"><label class="form-label">Jours acquis</label><input v-model="f.joursAcquis" type="number" step="0.5" min="0" class="form-control" required></div><div class="col-md-3"><label class="form-label">Jours reportés FIFO</label><input v-model="f.joursReportes" type="number" step="0.5" min="0" class="form-control" required></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary">Enregistrer</button></div></div></form><section class="card card-body"><h2 class="h5">Soldes enregistrés</h2><div v-for="s in soldes" :key="s.id" class="border-bottom py-2">{{s.employe?.prenom}} {{s.employe?.nom}} · Année {{s.annee}} · Acquis : {{s.joursAcquis}} · Reportés : {{s.joursReportes}} · Disponible : {{s.disponible}}</div></section></div></template>
